from z3 import Solver, Bool, Sum, And, sat

# Try bipartite graph with parts of size 14 and 14
n1 = 14
n2 = 14

# Variables: x[i][j] for i in 0..13, j in 0..13
x = [[Bool(f"x_{i}_{j}") for j in range(n2)] for i in range(n1)]

s = Solver()

# Row sums between 4 and 7
for i in range(n1):
    rs = Sum([x[i][j] for j in range(n2)])
    s.add(rs >= 4, rs <= 7)

# Column sums between 4 and 7
for j in range(n2):
    cs = Sum([x[i][j] for i in range(n1)])
    s.add(cs >= 4, cs <= 7)

# No 2x2 submatrix of all 1s (forbids 4-cycles)
for i1 in range(n1):
    for i2 in range(i1+1, n1):
        for j1 in range(n2):
            for j2 in range(j1+1, n2):
                s.add(Sum([x[i1][j1], x[i1][j2], x[i2][j1], x[i2][j2]]) <= 3)

print("Solving...")
res = s.check()
print("Result:", res)

if res == sat:
    m = s.model()
    edges = []
    for i in range(n1):
        for j in range(n2):
            if m[x[i][j]]:
                edges.append((i, j + n1))

    print("Number of edges:", len(edges))
    print("Edges:", edges)

    # Check degrees
    deg = [0] * (n1 + n2)
    for u, v in edges:
        deg[u] += 1
        deg[v] += 1

    print("Degrees:", deg)
    print("Min degree:", min(deg), "Max degree:", max(deg))

    # Check no 4-cycles
    edge_set = set(edges)
    for i1 in range(n1):
        for i2 in range(i1+1, n1):
            for j1 in range(n2):
                for j2 in range(j1+1, n2):
                    if (i1, j1+n1) in edge_set and (i1, j2+n1) in edge_set and (i2, j1+n1) in edge_set and (i2, j2+n1) in edge_set:
                        print("FOUND 4-CYCLE!")
                        exit()

    # Check no triangles (should be none since bipartite)
    adj = [set() for _ in range(n1 + n2)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    for u in range(n1 + n2):
        for v in adj[u]:
            for w in adj[u]:
                if v < w and w in adj[v]:
                    print("FOUND TRIANGLE!")
                    exit()

    print("No triangles or 4-cycles found.")
    print("Graph is valid!")
